use funder_name::FunderNameFeatures;
use serde_json::{Value, json};
use std::collections::BTreeMap;

const MEMBER: &str = "00000000-0000-0000-0000-000000000001";

pub(super) struct PolicyCase {
    pub name: String,
    pub budget: usize,
    input: ResolutionInput,
}

impl PolicyCase {
    pub fn rows(&self) -> Vec<super::Row> {
        self.input.scoring_input(self.budget).rows.into_iter().map(|r| super::Row {
            key:r.key, name:r.name, address:r.address, blocking_keys:r.blocking_keys, needs_resolution:r.needs_resolution,
        }).collect()
    }

    pub fn resolve(&self, pairs: &[super::Pair]) -> Value {
        let scoring = self.input.scoring_input(self.budget);
        let pairs = pairs.iter().map(|p| ScoredPair { left:p.left.clone(), right:p.right.clone(), probability:p.probability, name_level:p.name_level, address_level:p.address_level }).collect();
        let result = ScoredPairs::checked(pairs, json!({"prototype":true}), &scoring)
            .and_then(|scores| ResolvedDeclarations::from_scored(&self.input, &scoring, scores, "comparison-run"));
        match result {
            Ok(result) => {
                let decisions = result.pairs.iter().map(|p| json!({"left":p.left_funder_id,"right":p.right_funder_id,"disposition":p.disposition,"reason":p.reason})).collect::<Vec<_>>();
                json!({"observations":result.observations,"attributions":result.attributions,"pair_decisions":decisions})
            }
            Err(e) => json!({"error":e.to_string()}),
        }
    }
}

fn observation(id: u32, name: Option<&str>, address: Option<&str>, kind: Option<&str>, company: Option<&str>, role: FunderRole) -> Observation {
    let features = FunderNameFeatures::from_name(name);
    let role_name = match role { FunderRole::Donor => "donor", FunderRole::Payer => "payer", FunderRole::UltimatePayer => "ultimate_payer" };
    Observation {
        funder_id:serde_json::from_value(json!(format!("{MEMBER}/{id}/1/declaration/{role_name}"))).unwrap(),
        member_id:MEMBER.into(), declaration_id:id, register_id:1, role,
        source_scope:"declaration".into(), source_pointer:"/versions/0/fields".into(),
        funding_entry_id:None, funding_ordinal:None,
        donor_kind:kind.map(str::to_owned), donor_company_number:company.map(str::to_owned),
        name_raw:features.name_raw, name_normalized:features.name_normalized,
        organisation_core:features.organisation_core, alias_normalized:features.alias_normalized,
        address_normalized:address.map(str::to_owned), address_match_quality:AddressMatchQuality::from_normalized(address),
    }
}

fn funding(mut observation: Observation, ordinal: u32) -> Observation {
    let role = match observation.role { FunderRole::Donor => "donor", FunderRole::Payer => "payer", FunderRole::UltimatePayer => "ultimate_payer" };
    let id = format!("{MEMBER}/{}/1/funding/{ordinal}", observation.declaration_id);
    observation.funder_id = serde_json::from_value(json!(format!("{id}/{role}"))).unwrap();
    observation.funding_entry_id = Some(serde_json::from_value(json!(id)).unwrap());
    observation.funding_ordinal = Some(ordinal);
    observation.source_scope = "funding_entry".into();
    observation
}

fn payment(id: u32, ordinal: u32, parent: Option<u32>, flag: Option<bool>, observations: &[Observation]) -> Payment {
    let mut payment = Payment {
        funding_entry_id:serde_json::from_value(json!(format!("{MEMBER}/{id}/1/funding/{ordinal}"))).unwrap(),
        member_id:MEMBER.into(), parliament_member_id:1, declaration_id:id, register_id:1, funding_ordinal:ordinal,
        parent_declaration_id:parent, is_ultimate_payer_different:flag,
        donor_funder_id:None, payer_funder_id:None, ultimate_payer_funder_id:None,
    };
    for observation in observations.iter().filter(|o| o.funding_entry_id.as_ref() == Some(&payment.funding_entry_id)) {
        match observation.role {
            FunderRole::Donor => payment.donor_funder_id = Some(observation.funder_id.clone()),
            FunderRole::Payer => payment.payer_funder_id = Some(observation.funder_id.clone()),
            FunderRole::UltimatePayer => payment.ultimate_payer_funder_id = Some(observation.funder_id.clone()),
        }
    }
    payment
}

