    case["pairs"], _ = reference.original_prediction(model, case["rows"])
    print(f"Splink {case['name']}: {len(case['pairs'])} pairs")
Path(sys.argv[2]).write_text(json.dumps(cases, indent=2, ensure_ascii=False) + "\n")
